\copy (with cl as (select distinct regexp_replace(lower(name),'\s+(lv\.?\s*\d+|ex|gx|v|vmax|vstar)$','') as n from marketplace_search_candidates where expansion_name ilike '%classic%' and expansion_name ilike '%ex deck') select s.version, s.source, c.card_id, c.ct_id, c.name, c.expansion_name, c.card_number, c.rarity, c.artist, coalesce(c.image_url,'') as image_url, c.item_kind, c.product_type from marketplace_search_candidates c join pokoin_version_sets s on s.version=c.version where exists (select 1 from cl where lower(c.name) = cl.n or lower(c.name) like cl.n||' %') order by c.card_id) to stdout with (format csv, delimiter E'\t', header true)
